export function getBTechSem7UnitKnowledge(subjectName: string, unitNumber: number): TopicKnowledge | null {
  const s = subjectName.toLowerCase().trim();
  const key = `${s}:::u${unitNumber}`;
  if (btechSem7Knowledge[key]) {
    return btechSem7Knowledge[key];
  }
  // Fuzzy match on subject name
  for (const [k, v] of Object.entries(btechSem7Knowledge)) {
    const [subKey, uKey] = k.split(":::u");
    if (uKey === String(unitNumber) && (s.includes(subKey) || subKey.includes(s))) {
      return v;
    }
  }
  return null;
}
